        /// <summary>A shared species file (format 1): "Clawed red-eye" by "Sample", red-eyed tree frogs with two copies of claws.</summary>
        private const string SpeciesSample =
            "FTSP1:Y2RgYOBzzkksT01RKEpN0U2tTGULTswtyEllZFRgYGRgaLBnQAX2ELEGew6YCDORygA=.6688e25f";

        /// <summary>A blueprint (format 1): "Rock and log", two parts.</summary>
        private const string BlueprintSample =
            "FTBP1:AQAAAAxSb2NrIGFuZCBsb2cCAAAAAAAAYEAAAIA/AAAAAAAAwD8AAAAAAAAAAgAAYMAAAIC/AADwQQAAgD8AAAAAAAAA";

        private static IEnumerable<int> Versions()
        {
            for (int v = 1; v <= Samples.Length; v++) yield return v;
        }

        private static byte[] Sample(int version) => System.Convert.FromBase64String(Samples[version - 1]);

        [Test]
        public void EverySaveVersion_HasAFrozenSample()
        {
            Assert.AreEqual(SaveSystem.CurrentVersion, Samples.Length,
                "Each save version needs a frozen sample. After bumping SaveSystem.CurrentVersion, add a sample made by the new game (see docs/SAVE_FORMAT.md).");
            for (int v = 1; v <= Samples.Length; v++)
                Assert.AreEqual(v, System.BitConverter.ToInt32(Sample(v), 4), "sample " + v + " should be a version " + v + " save");
        }

        [Test]
        public void NewestSample_IsWrittenBackByteForByte()
        {
            byte[] original = Sample(SaveSystem.CurrentVersion);
            byte[] again = SaveSystem.ToBytes(SaveSystem.FromBytes(original));
            Assert.AreEqual(original.Length, again.Length,
                "Saving the newest sample again changed its size. The save layout changed: bump SaveSystem.CurrentVersion and add a sample (see docs/SAVE_FORMAT.md).");
            CollectionAssert.AreEqual(original, again,
                "Saving the newest sample again changed its bytes. The save layout changed: bump SaveSystem.CurrentVersion and add a sample (see docs/SAVE_FORMAT.md).");
        }

        [TestCaseSource(nameof(Versions))]
        public void OldSave_UpgradesToTheCurrentVersion(int version)
        {
            var old = SaveSystem.FromBytes(Sample(version));
            byte[] upgraded = SaveSystem.ToBytes(old);
            Assert.AreEqual(SaveSystem.CurrentVersion, System.BitConverter.ToInt32(upgraded, 4));

            // The upgraded save holds the same tank...
            var back = SaveSystem.FromBytes(upgraded);
            Assert.AreEqual(old.Seed, back.Seed);
            Assert.AreEqual(old.SimTime, back.SimTime);
            Assert.AreEqual(old.HalfSizeX, back.HalfSizeX);
            Assert.AreEqual(old.HalfSizeZ, back.HalfSizeZ);
            Assert.AreEqual(old.Agents.Count, back.Agents.Count);
            Assert.AreEqual(old.Agents.NextId, back.Agents.NextId);
            for (int i = 0; i < old.Agents.Count; i++)
            {
                Assert.AreEqual(old.Agents.Id[i], back.Agents.Id[i]);
                Assert.AreEqual(old.Agents.PosX[i], back.Agents.PosX[i]);
                Assert.AreEqual(old.Agents.PosZ[i], back.Agents.PosZ[i]);
            }
            Assert.AreEqual(old.Parts.Count, back.Parts.Count);
            Assert.AreEqual(old.Devices.Count, back.Devices.Count);
            Assert.AreEqual(old.Registered.Count, back.Registered.Count);
            Assert.AreEqual(old.Economy.Enabled, back.Economy.Enabled);
            Assert.AreEqual(old.Map.ToCode(), back.Map.ToCode());
            Assert.AreEqual(old.Terrain.Height, back.Terrain.Height);
            // ...and saving it once more changes nothing.
            CollectionAssert.AreEqual(upgraded, SaveSystem.ToBytes(back), "an upgraded save is stable");

            // It also plays on: a minute of game time with nothing broken.
            var loop = SimulationFactory.CreateDefault(back);
            for (int k = 0; k < 120; k++) loop.Advance(0.5);
            var a = back.Agents;
            for (int i = 0; i < a.Count; i++)
                Assert.IsFalse(float.IsNaN(a.PosX[i]) || float.IsNaN(a.PosZ[i]) || float.IsNaN(a.Hunger[i]),
                    "agent " + a.Id[i] + " went wrong after loading a version " + version + " save");
            Assert.DoesNotThrow(() => SaveSystem.FromBytes(SaveSystem.ToBytes(back)));
        }

        [Test]
        public void Version12Save_StillLoads()
        {
            var w = SaveSystem.FromBytes(Sample(12));
            Assert.AreEqual(4004UL, w.Seed);
            Assert.AreEqual("FTMAP1:islands:4004:standard:100:100:100", w.Map.ToCode());
            Assert.AreEqual(3, w.FrogCount());
            Assert.AreEqual(2, w.Parts.Count);
            Assert.AreEqual(3, w.Style);
            Assert.IsTrue(w.Economy.Enabled);
            Assert.AreEqual(749.55, w.Economy.Money, 0.01);
            Assert.AreEqual(1, w.Registered.Count);
            Assert.AreEqual("Island hopper", w.Registered[0].Name);
            Assert.IsNotNull(w.Scenario);
            Assert.AreEqual(4, w.Scenario.Id);
            Assert.AreEqual(ScenarioStatus.Playing, w.Scenario.Status);
            Assert.AreEqual(80.0, w.SimTime, 0.001);
        }

        [Test]
        public void Version13Save_StillLoads()
        {
            var w = SaveSystem.FromBytes(Sample(13));
            Assert.AreEqual(1313UL, w.Seed);
            Assert.AreEqual(2, w.FrogCount());
            Assert.AreEqual(2, w.Parts.PlayPieces.Count);
            var a = w.Agents;
            int rider = a.IndexOf(1), other = a.IndexOf(2);
            Assert.AreEqual(Goal.Play, a.Goal[rider]);
            Assert.AreEqual(1, a.RidePart[rider], "still on the slide");
            Assert.AreEqual(3f, a.RideTime[rider], 0.01f);
            Assert.AreEqual(0.256f, a.Play[other], 0.001f);
            Assert.Greater(a.Fun[other], 0.99f);
            Assert.AreEqual(3.0, w.SimTime, 0.001);
        }

        [Test]
        public void SharedMapSample_StillOpensWithNoDifferences()
        {
            var map = MapFile.FromText(MapSample);
            Assert.AreEqual("Dune garden", map.Name);
            Assert.AreEqual("Sample", map.Author);
            Assert.AreEqual("d79daf6f", map.Fingerprint);
            Assert.AreEqual(2, map.Parts.Count);
            Assert.AreEqual(4, map.Devices.Count);
            Assert.AreEqual("FTMAP1:desert:4242:large:100:100:100", map.Settings.ToCode());

            // Played on this computer and shared on again, it is the very same map. (The fingerprint is
            // taken from the uncompressed map, so this holds even where compression differs.)
            var w = map.CreateWorld(2, 4);
            Assert.AreEqual(2, w.Style);
            var again = MapFile.FromWorld(w, map.Name, map.Author);
            again.ToText();
            Assert.AreEqual(map.Fingerprint, again.Fingerprint);
        }

        [Test]
        public void SharedSpeciesSample_StillArrives()
        {
            var s = SpeciesFile.FromText(SpeciesSample);
            Assert.AreEqual("Clawed red-eye", s.Name);
            Assert.AreEqual("Sample", s.Author);
            Assert.AreEqual("6688e25f", s.Fingerprint);
            Assert.AreEqual(2097409, s.Type);
            var w = World.CreateStarterTank(31, 2, 4);
            Assert.IsTrue(s.AddTo(w, 0f, 0f, out string why), why);
            Assert.AreEqual("Clawed red-eye", w.Registered[0].Name);
        }

        [Test]
        public void BlueprintSample_StillReadsWithNoDifferences()
        {
            var b = Blueprint.FromText(BlueprintSample);
            Assert.AreEqual("Rock and log", b.Name);
            Assert.AreEqual(2, b.Parts.Count);
            Assert.AreEqual(BlueprintSample, b.ToText());
        }

        [Test]
        public void BlueprintFromANewerGame_IsRefusedWithAClearMessage()
        {
            byte[] data = System.Convert.FromBase64String(BlueprintSample.Substring(Blueprint.TextPrefix.Length));
            System.Array.Copy(System.BitConverter.GetBytes(99), 0, data, 0, 4);
            var e = Assert.Throws<SaveFormatException>(() => Blueprint.FromText(Blueprint.TextPrefix + System.Convert.ToBase64String(data)));
            StringAssert.Contains("newer", e.Message);
        }
    }
